window.RP_SESSION={"id":"S-8e1231167356","messages":[{"id":"RP-0106976","time":"2026-04-10T15:05:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"책을 코 앞에 두고 힘겹게 읽고 있다","characters":["P-5d0c306440d0"]},{"id":"RP-0106977","time":"2026-04-10T15:05:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"진짜로","characters":["P-5d0c306440d0"]},{"id":"RP-0106978","time":"2026-04-10T15:05:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"할게 없다고","characters":["P-5d0c306440d0"]},{"id":"RP-0106979","time":"2026-04-10T15:10:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"처음 우린 차는 마시지 않고 버리고...\"","characters":["P-5d0c306440d0"]},{"id":"RP-0106980","time":"2026-04-10T15:10:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"지켜야 될 예절이 왜이리 많은거지...","characters":["P-5d0c306440d0"]},{"id":"RP-0106981","time":"2026-04-10T15:10:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"그냥 우려 마시면 안되나","characters":["P-5d0c306440d0"]},{"id":"RP-0106982","time":"2026-04-10T15:10:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-5d0c306440d0"]},{"id":"RP-0106983","time":"2026-04-10T15:11:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"보다보니 머리가 아프다","characters":["P-5d0c306440d0"]},{"id":"RP-0106984","time":"2026-04-10T15:11:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"조용히 책을 덮는다","characters":["P-5d0c306440d0"]},{"id":"RP-0106985","time":"2026-04-10T15:11:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"후....\"","characters":["P-5d0c306440d0"]},{"id":"RP-0106986","time":"2026-04-10T15:16:00+09:00","room":"RP","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 책 어, 어렵죠? 저도 글 잘 모, 못 읽어요... \"\n\n모닥불에서 물을 끓이고 있는 레마.","characters":["P-fec1db60d51e"]},{"id":"RP-0106987","time":"2026-04-10T15:17:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"....?\"","characters":["P-5d0c306440d0"]},{"id":"RP-0106988","time":"2026-04-10T15:18:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"글을 못 읽는건, 배우면 되죠\"","characters":["P-5d0c306440d0"]},{"id":"RP-0106989","time":"2026-04-10T15:18:00+09:00","room":"RP","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 마, 맞아요. 그래서 길드원 분들한테 제, 제가 모르는 단어 같은 것도 배, 배우고 있어요. 정말 조, 좋은 분들이신 것 같아요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-0106990","time":"2026-04-10T15:22:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"이 길드엔 좋은 사람들도 많이 있죠.. 그래서 그쪽은 신입인가요?\"","characters":["P-5d0c306440d0"]},{"id":"RP-0106991","time":"2026-04-10T15:23:00+09:00","room":"RP","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 네, 레마 캐롤라인이라고 해, 해요. 자, 잘 부탁드립니다. \"","characters":["P-fec1db60d51e"]},{"id":"RP-0106992","time":"2026-04-10T15:24:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"폴라리스, 다들 리스라 불러요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0106993","time":"2026-04-10T15:25:00+09:00","room":"RP","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 폴라리스, 머, 멋진 이름이네요! 엘프 분들은 다, 다들 네 글자로 이, 이름을 짓는건가요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-0106994","time":"2026-04-10T15:26:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"아니요, 인간이나 티플링과 마찬가지로 원하는데로 이름 짓죠\"","characters":["P-5d0c306440d0"]},{"id":"RP-0106995","time":"2026-04-10T15:33:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"다들 또 밖에서 불 피우고 노가리 까는 중이야?\"","characters":["P-96ab98d2591c"]},{"id":"RP-0106996","time":"2026-04-10T15:34:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"아카쿠씨 오랜만이에요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0106997","time":"2026-04-10T15:34:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"오랜만인가? 하긴 요즘 이것저것 일이 많아서 길드 회관에서 쉬지는 못 했으니까...\"","characters":["P-96ab98d2591c"]},{"id":"RP-0106998","time":"2026-04-10T15:35:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"드디어 미샤의 눈치를 보지 않고 쉬어도 된다 이말이야!\"","characters":["P-96ab98d2591c"]},{"id":"RP-0106999","time":"2026-04-10T15:35:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"아카쿠는 흥이 겨운지 칵칵 웃습니다.","characters":["P-96ab98d2591c"]},{"id":"RP-0107000","time":"2026-04-10T15:35:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"뭔일 있으셨었나요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107001","time":"2026-04-10T15:36:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그간의 낭비벽이 들키고 몰래 쓴만큼 벌어온거지!\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107002","time":"2026-04-10T15:36:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"이제 데미간 마켓에서 몰래 한잔하는 삶은 없어질거야..\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107003","time":"2026-04-10T15:36:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"...\" 자업자득아닌가","characters":["P-5d0c306440d0"]},{"id":"RP-0107004","time":"2026-04-10T15:37:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그런 이유에서 하루종일 길드 회관에서 카드놀이나 하려고 했는데 스텔라에게 붙들려서 사무실에서 자료만들다가 이 시간까지 있었네...\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107005","time":"2026-04-10T15:37:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"션이 공대장이 되면서 준비할 일이 많이 있나봐?\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107006","time":"2026-04-10T15:38:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그런고로 여기서 뭘 하고 있는 중이야? 보통 모닥불을 피우면 뭔가 대화 상대가 필요하거나 고민이 있는 사람들이잖아? 거기 티플링 친구도 처음 보는 얼굴이고. 안녕~!\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107007","time":"2026-04-10T15:39:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"고민.. 은 없긴 한데요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107008","time":"2026-04-10T15:39:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"그냥 심심하니, 앉아 있었던 것 뿐입니다\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107009","time":"2026-04-10T15:39:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그렇다면 심심하다는게 고민거리고 사람을 불러모으려고 불을 피운건가?\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107010","time":"2026-04-10T15:40:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"심심하다... 흠... 요즘 딱히 뭔가 대단한 일이 없어서 재미있는 이야기거리가 떠오르는게 없는데...\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107011","time":"2026-04-10T15:41:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"굳이 어렵게 이야기 꺼낼 필요는 없어요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107012","time":"2026-04-10T15:42:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"나도 시간 까먹기는 환영이니까. 심심하잖아? 재미있는 이야기거리 흠... 잠깐만 조금 지루할 수도 있지만 성경에 있던 내용 중에서 조금 골라볼게.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107013","time":"2026-04-10T15:43:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"성경...\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107014","time":"2026-04-10T15:43:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"흠","characters":["P-5d0c306440d0"]},{"id":"RP-0107015","time":"2026-04-10T15:43:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"딱딱한 이야기말고 아이들에게 할만한 그런 내용도 많으니까\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107016","time":"2026-04-10T15:45:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"아! 하나 떠올랐어.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107017","time":"2026-04-10T15:45:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"폴라리스, 혹시 과거를 바꾸고 싶다던가 하는 생각이 든 적이 있어?\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107018","time":"2026-04-10T15:47:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"혹은 다가올 미래가 두렵다던가?\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107019","time":"2026-04-10T15:48:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"바꾸고 싶은 과거라...\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107020","time":"2026-04-10T15:48:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"바꾸고 싶은 과거는 많이 있지만... 설령 그때로 돌아간다 하더라도 바꿀 수 있을거 같진 않네요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107021","time":"2026-04-10T15:49:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"아무래도 엘프니까 오랜 시간을 살았고... 뭐 많은 일이 있었겠지.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107022","time":"2026-04-10T15:49:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"내가 할 이야기는 엘리아셉과 모래시계 이야기야.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107023","time":"2026-04-10T15:50:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"옛적 엘리아셉이라 하는 서기관이 있었더라. 그는 율법을 적는 자요, 밤마다 등불 아래에서 주의 말씀을 읽는 자였으나... 아니다 격식없이 말하는게 낫겠네.\"\n\n\"흠흠\"\n\n아카쿠는 목을 풀고 다시 이야기를 시작했습니다.","characters":["P-96ab98d2591c"]},{"id":"RP-0107024","time":"2026-04-10T15:51:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"옛날에 엘리아셉이라는 서기관이 있었어. 그는 신앙심이 투철한 사람이었지. 그에게는 오랫동안 가슴에 남은 후회가 있었어.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107025","time":"2026-04-10T15:55:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"어느날 자기도 모르게 이야기를 하게되는데... '내가 동생에게 한마디만 했더라면! 동생이 그렇게 죽지 않았을텐데!'. 그 순간 갑자기 빛이 나더니 한 천사가 내려와서 엘리아셉에게 이야기를 하는데!\"\n\n\"사람의 마음은 지나간 날을 붙들려하고 오지 않은 날을 훔쳐보려 한다. 현재에 충실하며 얽매이지 말지어다. 라고 이야기를 하니 엘리아셉은...!\"\n\n\"하오나 저에게 기회가 있더라면 더 나은 무언가가 있을지도 모릅니다 라고 하더라.\"\n\n\"하니 천사가 엘리아셉에게 모래시계를 쥐어주고서는 말하되. 사람의 마음은 지나간 날을 붙들려 하고, 오지 않은 날을 훔쳐보려 한다. 내 너에게 기회를 주건데 그 뜻을 한번 이루어보거라.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107026","time":"2026-04-10T15:56:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"말을 길게 했지만 엘리아셉이 과거 때문에 힘들어하니까 천사가 나타나서 엘리아셉에게 신묘한 모래시계를 줬다는 이야기야.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107027","time":"2026-04-10T15:56:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"선글라스로 인해 눈을 감은건지 뜬건지 모르겠다","characters":["P-5d0c306440d0"]},{"id":"RP-0107028","time":"2026-04-10T15:56:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"헉쓰","characters":["P-96ab98d2591c"]},{"id":"RP-0107029","time":"2026-04-10T15:56:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"어차피 눈도 안보이잖아!","characters":["P-96ab98d2591c"]},{"id":"RP-0107030","time":"2026-04-10T15:57:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"...크흠\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107031","time":"2026-04-10T15:57:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"그래서 아카쿠씨가 하고 싶은 말은 뭔가요?\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107032","time":"2026-04-10T15:57:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"흠... 지루한가보네? 이야기를 축약해서 말하면 결국 엘리아셉은 과거를 바꿔보려고 했지만 잘 되지 않았고. 미래를 살피고 준비했지만 실패했어.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107033","time":"2026-04-10T15:58:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그리고 결과적으로 엘리아셉은 현재에 충실해야한다는 것을 깨닿게 되는 이야기야.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107034","time":"2026-04-10T15:58:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"끄덕","characters":["P-5d0c306440d0"]},{"id":"RP-0107035","time":"2026-04-10T15:58:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"그렇군요","characters":["P-5d0c306440d0"]},{"id":"RP-0107036","time":"2026-04-10T15:58:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"음음...","characters":["P-5d0c306440d0"]},{"id":"RP-0107037","time":"2026-04-10T15:58:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"...","characters":["P-5d0c306440d0"]},{"id":"RP-0107038","time":"2026-04-10T15:58:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그냥 뭐. 심심하다길래 말할거리를 고른건데 실패한 것 같네.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107039","time":"2026-04-10T15:59:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"음... 이야기가 시작하기 전에 말했지만\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107040","time":"2026-04-10T15:59:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"조금 더 깊게 이야기하자면 사실 이 이야기는 카카투 교단에서 많은 의견이 갈려. 카카투는 [시간]을 다루는 존재는 아니니까.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107041","time":"2026-04-10T15:59:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"전... 과거를 바꿀 수 있다고 생각하는 편은 아니니깐요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107042","time":"2026-04-10T15:59:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"어딘가에 시간을 다루는 존재가 있다면 과거나 미래 여행도 가능하지 않을까? 라는 생각이 들었거든.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107043","time":"2026-04-10T15:59:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"과거를 바꾸지는 않더라도...\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107044","time":"2026-04-10T15:59:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"있겠죠\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107045","time":"2026-04-10T16:00:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"잠깐 놀러가서 보고 싶거나 그리운 것을 보는 것은 가능하지 않을까?\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107046","time":"2026-04-10T16:00:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"아, 아카쿠 씨는... 모르나\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107047","time":"2026-04-10T16:00:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"전에 미래의 딘과 베레데르가 찾아왔었어요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107048","time":"2026-04-10T16:00:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"... 뭐?!\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107049","time":"2026-04-10T16:00:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"둘이 커서 어른이 된 모습이라... 예상이 안가는걸?\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107050","time":"2026-04-10T16:00:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"시간을 여행하는 유물이 있다고 하더라고요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107051","time":"2026-04-10T16:00:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"알게모르게 이상한 사건에 모두 휘말렸구나.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107052","time":"2026-04-10T16:01:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"미래의 딘과 베레디르가 뭐래?\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107053","time":"2026-04-10T16:01:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"우리들은 잘 지내고 있다고 했어?\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107054","time":"2026-04-10T16:02:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"아뇨, 싸우러 왔어요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107055","time":"2026-04-10T16:02:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"딘이 세계를 정복하고 싶다고 했었나?\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107056","time":"2026-04-10T16:02:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"하하","characters":["P-5d0c306440d0"]},{"id":"RP-0107057","time":"2026-04-10T16:02:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"어디 개꿈 꾼 것 아니야?\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107058","time":"2026-04-10T16:02:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그 서글서글한 녀석이 와서 그런다고?\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107059","time":"2026-04-10T16:03:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"미래의 길드원이라...\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107060","time":"2026-04-10T16:03:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"아까 이야기를 조금 말하자면... 아마 네가 만난 딘은 여러가지 가능성 중 하나 아닐까?\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107061","time":"2026-04-10T16:03:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"그렇겠죠\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107062","time":"2026-04-10T16:04:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"션도 걱정하더라고요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107063","time":"2026-04-10T16:04:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"미래의 길드원이 어떤 모습을 하고있을지 생각해보면 제법 재미있을 것 같네.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107064","time":"2026-04-10T16:04:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"그러게요, 어린 친구들은 다 자라있겠죠\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107065","time":"2026-04-10T16:05:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"루체랑 모카도 있고 이제 겨우 성인 언저리에 있는 친구들도 많으니까.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107066","time":"2026-04-10T16:06:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":"V","characters":[]},{"id":"RP-0107067","time":"2026-04-10T16:06:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"그럼요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107068","time":"2026-04-10T16:06:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"....\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107069","time":"2026-04-10T16:06:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"나이 많은 사람들은... 뭐, 은퇴하겠죠\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107070","time":"2026-04-10T16:06:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"사실 그런 부분에서 조금 걱정은 된다고 생각해.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107071","time":"2026-04-10T16:06:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"어떤 부분에서요?\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107072","time":"2026-04-10T16:07:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"아무래도 어린 나이부터 길드에서 지낸다는게 과연 정서적인 교육으로 좋은건가... 하는 생각. 물론 골기가 법 상으로는 성인이지만 아직 자립은 힘든 친구들이라고 생각하거든.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107073","time":"2026-04-10T16:07:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"무언가 확실한 직업을 가지기 보다는 주어진 의뢰를 하는 그런 삶을 살면서 지내는 친구들도 많으니까.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107074","time":"2026-04-10T16:08:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"내 생각에 뭘 하고 싶은지 확실하게 정하지 못한 친구들이 클램시의 이념에 홀려서 따라온 경우들이 많지 않았나 하는 생각이야.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107075","time":"2026-04-10T16:08:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"... 자신이 선택한 일을 싫어하던가요?\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107076","time":"2026-04-10T16:08:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"아니 대부분 좋아하지. 하지만 그렇기 때문에 오히려 더 걱정이야.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107077","time":"2026-04-10T16:09:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"대장장이가 되려면 어릴 때부터 도제로 지내야하고. 신관이 되려면 교리 교육을 받아야하며, 기사가 되기 위해서는 검술 교육을 받아야하고, 마법사가 되기 위해서는 교육 기관에 들어가야하는데.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107078","time":"2026-04-10T16:09:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"사실상 그런 기회라 길드에서 주어지는 것은 아니니까.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107079","time":"2026-04-10T16:09:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"물론, 배울 멘토들은 많이 있지만 그 환경 자체가 잘 구성되어 있다는 생각을 하지는 않아.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107080","time":"2026-04-10T16:10:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"... 아카쿠씨, 길드는 교육 기관이 아닌걸요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107081","time":"2026-04-10T16:11:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그러니까, 어린 친구들이 길드에서 마냥 지내는 것에 걱정을 한다는 이야기지.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107082","time":"2026-04-10T16:11:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"아카쿠씨가 뭘 걱정하는 건지 알것 같아요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107083","time":"2026-04-10T16:12:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"뭐, 엘프들이야 잠깐 지내는 사이에 시간이 흘러갈테니 못 느낄 수도 있겠지만 길드에서 10년이란 시간을 보낸다고 할 때, 대장장이라면 견습에서 이제 한 사람 몫을 할테고... 뭐 다른 직업들도 비슷할테고.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107084","time":"2026-04-10T16:12:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"그들에게 '진짜'보호자가 없는게 걱정인거죠?\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107085","time":"2026-04-10T16:12:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"뭐, 그렇지. 사실상 내 오지랖이지만.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107086","time":"2026-04-10T16:12:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"항상 재미있고 행복하게 지낼 수는 없으니까. 물론 죄다 능력은 하나씩 있어서 그걸로 의뢰를 하면서 돈은 곧 잘 벌어오겠다만... 그것과는 다른 이야기라고 생각해.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107087","time":"2026-04-10T16:13:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"하지만, 아카쿠씨\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107088","time":"2026-04-10T16:13:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"이런 세상에서\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107089","time":"2026-04-10T16:13:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"보호자가 있는건 축복받은거지...\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107090","time":"2026-04-10T16:14:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"없는게 이상한게 아니에요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0107091","time":"2026-04-10T16:14:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"어쩌면 선글라스 뒷편에서 시선이 느껴져왔을 지도 모른다","characters":["P-5d0c306440d0"]},{"id":"RP-0107092","time":"2026-04-10T16:15:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"사실 이런 말을 하는 것 자체가 비겁하다는 것은 알아. 내가 그 친구들의 삶의 목적을 찾는 것을 도울 것도 아니고 그냥 꼰대마냥 그러면 안 되는데라고 말해봐야... 네 말대로 보호자도 아니고...\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107093","time":"2026-04-10T16:16:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"내가 무슨 말을 하는건지 원.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107094","time":"2026-04-10T16:18:00+09:00","room":"RP","name":"아카쿠","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"미안. 그냥 조금 감정적이 됐나봐. 모닥불 때문인가? 쓸데없이 부담스러운 이야기나 주절주절거렸네.\"","characters":["P-96ab98d2591c"]},{"id":"RP-0107095","time":"2026-04-10T16:18:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"아니에요\"","characters":["P-5d0c306440d0"]}]};
